  "growText": {
    "yourArea": "お住まいの地域",
    "outsideTropical": "{plant}は暖かい熱帯気候でよく育ち、ゾーン9未満では苦戦します。寒い地域では、冬に屋内へ移せる大きな鉢で育てましょう。",
    "outsideTree": "{plant}はお住まいのゾーン外でよく育ちます。地域に合う耐寒性品種を近くの園芸店に相談しましょう。",
    "outsideOther": "{plant}は通常、お住まいのゾーン外で栽培されます。微気候によっては鉢・レイズドベッド・温室でうまくいくこともあります。",
    "frost": "{plant}はお住まいのゾーンに合っていますが、霜の予報があります。夜の最低気温が安定して40°Fを超えるまで屋外への植え付けは待ちましょう。今は室内で種まきするのがおすすめです。",
    "heatCool": "{plant}は涼しい気温を好み、今の暑さでは苦戦します。80°Fを下回るまで待つか、朝日だけが当たる日陰に植えましょう。",
    "heatLover": "{plant}は暑さが大好きで、お住まいのゾーンでよく育ちます。早朝に植え、たっぷり水やりし、厚めのマルチで午後の暑さから根を守りましょう。",
    "heatOther": "{plant}は暑さに耐えますが、今は気温がかなり高いです。朝にたっぷり水やりし、マルチを敷き、最も暑い時間帯の植え替えは避けましょう。",
    "easy": "{plant}は初心者向けで、お住まいのゾーンにぴったりです。失敗に強く成長も早く、こまめな水やりと良い土に確かな収穫で応えてくれます。最初の一株におすすめ。",
    "hard": "{plant}は手間がかかりますが、{zone}で育てる価値は十分あります。土づくり、こまめな水やり、害虫チェックを大切に。努力は見事な収穫で報われます。",
    "medium": "{plant}は適期に植えれば{zone}で堅実に育ちます。堆肥で土づくりし、こまめに水やりし、風通しと健やかな成長のため株間を十分にとりましょう。",
  },
