  "growCrop": {
    "c1": "トマトは少し計画すればお住まいのゾーンでよく育ちます。最終霜の6〜8週間前に室内で種をまき、外気に慣らしてから、夜温が50°Fを超えるようになったら植え付けましょう。",
    "c2": "温帯ゾーンのピーマンは立ち上がりに暖かさが必要です。早めに室内で育苗し、土が温まってから定植すれば、晩夏に最も多く収穫できます。",
    "c3": "お住まいのゾーンではレタスは春と秋の作物です。夏の暑さでとう立ちするので、少しずつこまめにまき、午後は日陰を作ってシーズンを延ばしましょう。",
    "c4": "ほうれん草はお住まいのゾーンでは涼しい時期に向いています。早春と晩夏にまけば秋にも収穫できます。真夏にまくととう立ちします。",
    "c5": "ケールは温帯で最も育てやすい作物の一つで、冬の大半を越せます。真夏にまけば秋〜冬に収穫でき、初霜のあとは葉が甘くなります。",
    "c6": "アブラナ科はお住まいのゾーンでは夏の前後がベストです。室内で育苗して春どりにするか、真夏にまいてより良い秋どりにし、モンシロチョウ対策にネットをかけましょう。",
    "c7": "ニンジンは早春まきと、秋どり用の真夏まきでよく育ちます。深く石のない土で育て、間引きをしないと又根やいじけた根になります。",
    "c8": "ニンニクは温帯の定番作物で、冬の寒さを必要とします。秋に植え付けて球が分かれるのに必要な寒さに当て、真夏に下葉が枯れてきたら収穫しましょう。",
    "c9": "エンドウは涼しいシーズン初めが大好き。土が耕せるようになったらすぐまき、つるの支えを用意し、こまめに収穫を — 暑くなると実がつかなくなります。",
    "c10": "インゲンはお住まいのゾーンで頼れる夏作物ですが、冷たい土は苦手です。最終霜のあとにまき、数週間後にもう一度まき、こまめに収穫して株を長持ちさせましょう。",
    "c11": "寒さが過ぎれば、温帯の夏でよく育ちます。最終霜のあと肥えた土に植え、葉ではなく株元に水をやれば、予想以上に収穫できるでしょう。",
    "c12": "サツマイモはジャガイモとは別物で、暖かいシーズンが必要です。お住まいのゾーンはぎりぎりなので、最終霜から十分たって土が温まってから苗を植え、秋の初霜前に掘り上げましょう。",
    "c13": "ジャガイモはお住まいのゾーンの長く涼しい春に合っています。最終霜の2週間ほど前に種イモを植え、芽が伸びたら土寄せし、葉が枯れたら晩生種を収穫しましょう。",
    "c14": "イチゴはお住まいのゾーンでは多年草で、2年目によく実ります。春か秋に植え、実の下にマルチを敷いて清潔に保ち、最も寒い時期は株元を覆いましょう。",
    "c15": "バジルは温帯の菜園ではデリケートな存在です。夜温が確実に50°Fを超えるまで室内に置き、いちばん日当たりのよい場所で育て、摘心して開花を遅らせましょう。",
    "c16": "お住まいのゾーンには、暖かい地域にはない実つきに必要な冬の寒さがあります。休眠中に裸苗を植え、中心が開くように剪定し、実がつきすぎたら摘果して枝の負担を減らしましょう。",
    "c17": "トマトは暑いゾーンでよく育ちますが、夏を越すにはたっぷりの水やりとマルチが欠かせません。Solar Fire や Heatmaster など耐暑性品種を選びましょう。",
    "c18": "ピーマンは暑いゾーンに最適な野菜の一つで、暑さを好みたくさん実ります。水やりを欠かさなければ、長く収穫が楽しめます。",
    "c19": "バジルは暑く日当たりのよい環境が大好きで、お住まいのゾーンにぴったりです。最終霜後に日なたへ植え、花をこまめに摘んで葉の風味を保ちましょう。",
    "c20": "スイカは暑いゾーンにうってつけ — 暑さで生長も甘さも増します。株間を広くとり、週に一度たっぷり水をやれば、うれしい収穫が待っています。",
    "c21": "オクラは暑い気候に最適な野菜の一つで、ほとんど手間いらずで育ちます。日なたに植え、最盛期は2日おきに収穫しましょう。",
    "c22": "ナスは暑さが大好きで、暖かいゾーンでとてもよく育ちます。土を常に湿らせておけば、長く収穫できます。",
    "c23": "サツマイモは暑いゾーンにぴったりで、長い暖かいシーズンにたくさん実ります。最終霜後に苗を植え、つるが広がる場所を確保しましょう。",
    "c24": "ケールは寒いゾーンに最適な野菜の一つで、霜に当たると味が良くなります。晩夏に植えれば、寒波のたびに甘くなる秋〜初冬の収穫が楽しめます。",
    "c25": "ほうれん草は寒いゾーンでよく育ち、春いちばんに植えられる作物の一つです。軽い霜に耐え、涼しい気候で柔らかい葉をつけます。",
    "c26": "エンドウは寒いゾーンにぴったり — 涼しい気候を好み、春に土が耕せるようになればすぐまけます。暑くなる前にしっかり収穫できます。",
    "c27": "ジャガイモは長く涼しいシーズンのある寒いゾーンに向いています。早春に検査済みの種イモを植えれば、晩夏にたっぷり収穫できます。",
    "c28": "ニンジンは冷涼な気候でよく育ち、軽い霜に当たると甘みが増します。深くやわらかく石のない土にまけば、まっすぐ大きな根になります。",
    "c29": "ブロッコリーは寒いゾーンに最適 — 涼しい気温を好み、春か秋が最もよく育ちます。早めに室内で育苗し、涼しくなってから定植すれば上質な収穫が得られます。",
  },
