    "coloradoPotatoBeetle_name": "コロラドハムシ",
    "coloradoPotatoBeetle_description": "黒い縞模様のある丸みを帯びた黄色い甲虫で、赤くて背中の丸い幼虫が最もよく食べます。",
    "squashVineBorers_name": "カボチャのツル食い虫",
