    "japaneseBeetles_sign": "金属光沢のある緑色の甲虫が群れで食べ、葉をレースのように網目状にする。",
    "japaneseBeetles_damage": "葉脈の間の組織を食べて葉を網目状にし、花や果実もかじる。幼虫は根を傷める。",
    "cucumberBeetles_sign": "黄色と黒の縞模様または斑点のある甲虫で、細菌性萎凋病も広げる。",
    "cucumberBeetles_damage": "葉や花、茎をかじるうえ、何より厄介なことに、株を枯らす細菌性萎凋病やモザイクウイルスを媒介する。",
    "cutworms_sign": "苗が一晩で地際からばっさり切られ、太った灰色の丸まった幼虫がいる。",
