    "coloradoPotatoBeetle_sign": "黄橙色の縞模様の甲虫と、赤い背中の丸まった幼虫が葉を食い荒らす。",
    "coloradoPotatoBeetle_damage": "成虫も幼虫もジャガイモやナスの葉を食べ尽くし、食害がひどいと収穫が全滅することもある。",
    "squashVineBorers_sign": "カボチャ類のつるが突然しおれ、株元の穴の近くにおがくずのようなフンが見られる。",
    "squashVineBorers_damage": "主茎の中にトンネルを掘って水の流れを断つため、元気だったつるがほぼ一晩で枯れ崩れる。",
    "leafMiners_sign": "葉の表面のすぐ下に、白や薄茶色のくねくねした筋状のトンネルが見える。",
    "leafMiners_damage": "トンネルや斑点で光合成が落ち、葉物野菜は見栄えが悪くなり、株も弱る。",
    "scaleInsects_sign": "茎や葉裏に茶色や蝋状の小さなこぶが集まり、こすっても簡単には取れない。",
    "scaleInsects_damage": "樹液を吸って葉が黄変・落葉し、べたつく甘露がすす病になる。",
    "mealybugs_sign": "葉の付け根や茎のすき間に、白くふわふわした綿のような塊が潜んでいる。",
    "mealybugs_damage": "樹液を吸って株を弱らせ、べたつく甘露を出してすす病やアリを呼び寄せる。",
    "earwigs_sign": "一晩で柔らかい葉や花びらにギザギザの穴が開き、日中は尾にはさみのある虫が隠れている。",
    "earwigs_damage": "柔らかい葉や花、苗に不規則な穴を開けるが、ほかの害虫を食べてくれる面もある。",
    "grasshoppers_sign": "葉の縁から内側へ大きくギザギザにかじられ、近づくと虫が跳んで逃げる。",
    "grasshoppers_damage": "大群になると葉や茎、果実まで食べ尽くし、数日で花壇を丸裸にしてしまう。",
    "cabbageLoopers_sign": "淡い緑色の幼虫が体を輪のように曲げて進み、大きなギザギザの穴を残す。",
    "cabbageLoopers_damage": "葉に大きな穴を開け、結球部にももぐり込んで、フンで作物を汚す。",
    "cornEarworms_sign": "トウモロコシの穂先(またはトマトの果実)に幼虫がもぐり込み、入口にフンが付いている。",
